sp_widget.script:
(function() { data.compliance = { total: 0, compliant: 0, non_compliant: 0, rate: 0 };
  try { var gr = new GlideRecord("x_1433041_identi_0_application"); gr.addQuery("active", true); gr.setLimit(200); gr.query();
    while (gr.next()) { data.compliance.total++; var comp = parseInt(gr.getValue("completion_percent") || "0", 10); if (comp >= 80) data.compliance.compliant++; else data.compliance.non_compliant++; }
    if (data.compliance.total > 0) data.compliance.rate = Math.round((data.compliance.compliant / data.compliance.total) * 100);
  } catch (e) { gs.error("IBAR Compliance Report widget error: " + e.message); }
})();
